mapper.select:
SELECT EXISTS (
    SELECT 1
      FROM users
     WHERE user_id = #{userId}
)

mapper.insert:
INSERT INTO training_sessions (
    user_id
  , training_type
  , call_scenario_id
) VALUES (
    #{userId}
  , #{trainingType}
  , #{callScenarioId}
)

mapper.update:
UPDATE training_sessions
   SET ended_at = NOW()
     , score = #{score}
 WHERE session_id = #{sessionId}
   AND ended_at IS NULL

mapper.insert:
INSERT INTO session_results (
    session_id
  , result_type
  , call_item_id
  , item_order
  , score
  , attempts
  , detail_json
) VALUES (
    #{sessionId}
  , #{resultType}
  , #{callItemId}
  , #{itemOrder}
  , #{score}
  , #{attempts}
  , #{detailJson}
)

mapper.update:
UPDATE session_results
   SET score = #{score}
     , attempts = #{attempts}
     , detail_json = #{detailJson}
 WHERE result_id = #{resultId}
